/// <summary>
///     The <c>AVADirPartyQuickCreateFormFrm_AVALEAURLDS_Extension</c> class is the extension for <c>DirPartyQuickCreateForm</c>
/// </summary>
[ExtensionOf(FormDatasourceStr(DirPartyQuickCreateForm, AVALogisticsElectronicAddressURL))]
final class AVADirPartyQuickCreateFormFrm_AVALEAURLDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>written</c> method.
/// </summary>
public void written()
{
    next written();

    element.electronicAddressWrite(element.AVALogisticsElectronicAddressURL);
}

/// <summary>
///    AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean retVal = true;

    /*
    // validateWrite() and write() do not need next-call in COC to avoid error messages
    retVal = next validateWrite();
    */
    retVal = true;

    return retVal;
}

/// <summary>
///    AVA <c>writing</c> method.
/// </summary>
public void writing()
{
    LogisticsElectronicAddress locBuffer;

    next writing();

    locBuffer               = element.AVALogisticsElectronicAddressURL;
    locBuffer.Type          = LogisticsElectronicAddressMethodType::URL;
    locBuffer.Description   = strFmt("@SYS82282", "@SYS37016");
    locBuffer.IsPrimary     = true;
    locBuffer.IsMobilePhone = true;

    element.setElectronicAddressLocation();
}

/// <summary>
/// designed from N.Freidenberger 14.05.2024
/// </summary>
public void initValue()
{
    next initValue();

    if (element.args().menuItemName() ==  menuItemDisplayStr(AVAsmmBusRelQuickCopy))
    {
        smmBusRelTable                   copySmmBusRelTable = element.args().record();
        LogisticsElectronicAddress       copyLogisticsElectronicAddress  = DirParty::primaryElectronicAddress(copySmmBusRelTable.Party, LogisticsElectronicAddressMethodType::URL); 
        LogisticsElectronicAddress       newLogisticsElectronicAddress   = this.cursor();

        newLogisticsElectronicAddress.Locator = copyLogisticsElectronicAddress.Locator;
        element.setElectronicAddressLocation();
    }
}
